import React, { useState } from "react";
import { View, Text, TextInput, TouchableOpacity, Modal, StyleSheet } from "react-native";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

export default function App() {
  const [peso, setPeso] = useState("");
  const [altura, setAltura] = useState("");
  const [imc, setImc] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);

  const calcularIMC = () => {
    const pesoNum = parseFloat(peso.replace(",", "."));
    const alturaNum = parseFloat(altura.replace(",", "."));

    if (!peso || !altura) {
      toast.warn("Por favor, preencha todos os campos!");
      return;
    }

    if (pesoNum <= 0 || alturaNum <= 0) {
      toast.error("Os valores devem ser maiores que zero!");
      return;
    }

    if (isNaN(pesoNum) || isNaN(alturaNum)) {
      toast.error("Digite apenas números válidos!");
      return;
    }

    const valorIMC = pesoNum / (alturaNum * alturaNum);
    setImc(valorIMC.toFixed(2));
    setModalVisible(true);
  };

  const fecharModal = () => {
    setModalVisible(false);
  };

  const obterClassificacao = (valor) => {
    if (valor < 18.5) return "Abaixo do peso";
    if (valor < 24.9) return "Peso normal";
    if (valor < 29.9) return "Sobrepeso";
    if (valor < 34.9) return "Obesidade Grau I";
    if (valor < 39.9) return "Obesidade Grau II";
    return "Obesidade Grau III";
  };

  return (
    <View style={styles.container}>
      <Text style={styles.titulo}>Calculadora de IMC</Text>

      <TextInput
        style={styles.input}
        placeholder="Peso (kg)"
        keyboardType="numeric"
        value={peso}
        onChangeText={setPeso}
      />
      <TextInput
        style={styles.input}
        placeholder="Altura (m)"
        keyboardType="numeric"
        value={altura}
        onChangeText={setAltura}
      />

      <TouchableOpacity style={styles.botao} onPress={calcularIMC}>
        <Text style={styles.textoBotao}>Calcular</Text>
      </TouchableOpacity>

      {/* Modal para resultado */}
      <Modal visible={modalVisible} transparent animationType="slide">
        <View style={styles.modalContainer}>
          <View style={styles.modalContent}>
            <Text style={styles.resultado}>Seu IMC é {imc}</Text>
            <Text style={styles.classificacao}>{obterClassificacao(imc)}</Text>
            <TouchableOpacity style={styles.botaoFechar} onPress={fecharModal}>
              <Text style={styles.textoFechar}>Fechar</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {/* Toastify container (obrigatório para mostrar avisos) */}
      <ToastContainer position="top-center" autoClose={2500} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#f8f8f8",
    padding: 20,
  },
  titulo: {
    fontSize: 26,
    fontWeight: "bold",
    marginBottom: 20,
  },
  input: {
    width: "80%",
    borderWidth: 1,
    borderColor: "#ccc",
    borderRadius: 8,
    padding: 10,
    marginBottom: 15,
    backgroundColor: "#fff",
  },
  botao: {
    backgroundColor: "#007BFF",
    padding: 12,
    borderRadius: 8,
  },
  textoBotao: {
    color: "#fff",
    fontWeight: "bold",
  },
  modalContainer: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "rgba(0,0,0,0.5)",
  },
  modalContent: {
    backgroundColor: "#fff",
    borderRadius: 12,
    padding: 25,
    alignItems: "center",
    width: "80%",
  },
  resultado: {
    fontSize: 22,
    fontWeight: "bold",
    marginBottom: 10,
  },
  classificacao: {
    fontSize: 18,
    color: "#444",
    marginBottom: 20,
  },
  botaoFechar: {
    backgroundColor: "#FF4444",
    paddingVertical: 10,
    paddingHorizontal: 20,
    borderRadius: 8,
  },
  textoFechar: {
    color: "#fff",
    fontWeight: "bold",
  },
});
